    const titleField = stage.querySelector('[data-p="title"]');
    titleField.focus();
    stage.querySelector('[data-p="ok"]').addEventListener("click",()=>{
      m.title = titleField.value;
      m.desc = stage.querySelector('[data-p="desc"]').value;
      stage.innerHTML=""; btn.disabled=false;
      if(isNew){ addCard(m); input.value=""; input.focus(); }
      else { fillCard(existingCard, m, savedText); }
    });
